/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import { loadFont as loadSans } from "@remotion/google-fonts/Barlow";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useCallback,
  useContext,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  getRemotionEnvironment,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  Sequence,
  type SequenceControls,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (isDev()) {
      console.warn(`parseColor could not parse "${s}"; using black.`);
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    interpolate([resolveColorString(a), resolveColorString(b)], "oklch")(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * A token at partial opacity — for scrims, veils and inner washes.
 *
 * A scrim written as a literal `rgba(0,0,0,0.4)` is lit for a light surface and
 * does nothing on a dark one; `withAlpha(t.foreground, 0.4)` follows the theme
 * and a user's override. Resolves through `parseColor`, so it inherits the same
 * `var()` guard — an unresolvable token degrades to black rather than an
 * invalid colour string mid-render.
 */
function withAlpha(color: string, alpha: number): string {
  const { r, g, b } = parseColor(color);
  return formatRgb({ mode: "rgb", r, g, b, alpha });
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * A work chat filling itself in, the way the channel actually reads.
 *
 * Not bubbles: a transcript. An avatar, a name in bold, a quiet timestamp, and
 * the messages under them as plain lines — the shape every team tool has
 * settled on. Messages land one at a time; a second message from the same
 * person joins the group without repeating the name; and when somebody new
 * starts typing, three dots hold their line until the words arrive. The
 * transcript never creeps: it sits perfectly still between arrivals and then
 * scrolls, once, by exactly the room the new line needs.
 *
 * ## The layout came off a recording and it closes to the pixel
 *
 * Four numbers describe every vertical position in the scene, measured on a
 * 638 × 354 capture by thresholding the ink of eighty frames:
 *
 *     name → its first message      37.59
 *     message → message             46.01
 *     last message → next name      69.00
 *     first message, before any scroll, at   158.90
 *
 * That is not a model fitted to the frames, it is *checked* against them. Take
 * the first message's start, add the two arrivals' scroll (46.01 + 2 × 46.01),
 * and the oldest line lands at 20.87; the recording's last frame has it at 21.
 * Carry the same arithmetic down to the newest name and it predicts 138.9 where
 * the recording measures 139.00. Nine tenths of a pixel over a whole scene.
 *
 * ## The scroll is an event, not a drift
 *
 * Between arrivals the transcript is *byte-identical* frame to frame — the
 * measured movement is 0.00px for twenty-nine frames at the head of the clip and
 * for another eight in the middle. Everything that looks like life comes from
 * the arrivals themselves. `SCROLL` is one of those moves, measured: it
 * accelerates for four frames, peaks at 5.1px, and then spends three quarters of
 * a second arriving.
 *
 * A caveat, because it is measured and it is not reproduced: the recording's
 * two-row scroll runs about 1.6× faster in normalised time than its one-row
 * scroll — a longer move that takes *less* time, which is a browser's native
 * smooth-scroll heuristic and not something a scene should imitate. One curve
 * ships, taken from the one-row move, and a two-row move simply travels twice
 * as far along it.
 */

const { fontFamily: SANS } = loadSans("normal", {
  weights: ["400", "500", "600", "700"],
  subsets: ["latin"],
});

/* ─────────────────────────────────────────────────────────────────────────
   The transcript, in the recording's own 638 × 354 pixels
   ───────────────────────────────────────────────────────────────────────── */

const REF_W = 638;
const REF_H = 354;

/** Baseline of a group's first message, below the name. */
const NAME_GAP = 37.59;
/** Baseline to baseline, within a group. */
const MSG_GAP = 46.01;
/** Last message of a group to the next group's name. */
const GROUP_GAP = 69;
/** Where the oldest message sits before anything has arrived. */
const START_Y = 158.9;
/**
 * The line the newest message rests on, and the whole reason the transcript is
 * still between arrivals.
 *
 * It does not scroll on every message — the recording's second message lands
 * with the stack measurably motionless, 0.00px for twenty-nine frames. It
 * scrolls only by however far the newest baseline would fall *past* this line,
 * which is zero until the thread is tall enough to reach it. One constant
 * replaces a per-message "does this one scroll" flag, and it is what makes the
 * arithmetic close: 158.90 + 46.01 is above it and moves nothing; the next two
 * rows put the newest baseline at 311.50 and the scroll settles at exactly
 * 92.02, which is what the recording measures.
 */
const ANCHOR = 219.48;

/** The avatar is square, and its top sits this far above the name's baseline. */
const AVATAR = 70;
const AVATAR_X = 119.5;
const AVATAR_RISE = 28;
/** Left of the text column's box. Ink starts at 201.1 (name) and 202.4 (body). */
const TEXT_X = 202;

/** Body type. Cap height measured at 22.40px. */
const SIZE = 31.2;
/** The timestamp, measured on its digits: cap 18.09. */
const TIME_SIZE = 24.9;
/** Box top → baseline at `lineHeight: 1`. A face metric, measured, not guessed. */
const ASC = 28.95;

/** Typing dots: on the line the message will take, a little above its baseline. */
const DOT = 5;
const DOT_GAP = 8.4;
const DOT_RISE = 5.7;
/** A dot every this many seconds, then the ellipsis starts over. */
const DOT_BEAT = 0.1;
/**
 * Frames between a group's row opening and the group appearing in it.
 *
 * The room is made first and the person arrives into it: the recording starts
 * scrolling on frame 37 and does not paint the avatar, the name or the first
 * dot until frame 40. Three frames is nothing to watch and everything to match,
 * and it is also what the dots are timed from — anchor their cycle to the scroll
 * instead and the ellipsis is a step out of phase for its whole life.
 */
const LEAD = 3;

/**
 * One arrival's scroll, as (seconds since it started, share of the travel).
 *
 * Recovered by correlating each frame's vertical ink profile against the last —
 * which reads the move off every visible row at once rather than tracking one
 * word — and checked against the absolute baseline of the bold name row, which
 * agrees to a third of a pixel.
 */
const SCROLL: readonly (readonly [number, number])[] = [
  [0, 0],
  [0.0167, 0.004],
  [0.05, 0.016],
  [0.0833, 0.044],
  [0.1167, 0.093],
  [0.15, 0.178],
  [0.1833, 0.289],
  [0.2167, 0.398],
  [0.25, 0.486],
  [0.2833, 0.557],
  [0.3167, 0.616],
  [0.35, 0.663],
  [0.3833, 0.702],
  [0.4167, 0.737],
  [0.45, 0.767],
  [0.4833, 0.791],
  [0.5167, 0.814],
  [0.55, 0.834],
  [0.5833, 0.852],
  [0.6167, 0.867],
  [0.65, 0.881],
  [0.6917, 0.893],
  [0.7167, 0.903],
  [0.75, 0.912],
  [0.7833, 0.919],
  [1.1, 1],
];

/**
 * How far a line is faded, by its height in the frame.
 *
 * Read as an envelope over the whole clip: the brightest any pixel of a line
 * ever got at each height. Taking the maximum across every frame is what makes
 * it a property of the *position* — one sample would have read a line with no
 * ascenders as a dip in the gradient.
 *
 * It stops at a tenth rather than at nothing: the oldest line is cut off by the
 * frame, not erased by the fade.
 */
const FADE: readonly (readonly [number, number])[] = [
  [10, 0.098],
  [25, 0.125],
  [40, 0.149],
  [55, 0.216],
  [70, 0.357],
  [85, 0.518],
  [100, 0.651],
  [115, 0.843],
  [140, 0.98],
  [175, 1],
];

type Table = readonly (readonly [number, number])[];

/** Linear read of a rising table, clamped at both ends. */
function read(table: Table, x: number): number {
  const first = table[0];
  const last = table[table.length - 1];
  if (!first || !last) return 0;
  if (x <= first[0]) return first[1];
  if (x >= last[0]) return last[1];
  for (let i = 1; i < table.length; i++) {
    const hi = table[i];
    const lo = table[i - 1];
    if (hi && lo && x <= hi[0]) {
      return lo[1] + ((hi[1] - lo[1]) * (x - lo[0])) / (hi[0] - lo[0]);
    }
  }
  return last[1];
}

interface Line {
  /** Baseline in transcript space, before any scroll. */
  y: number;
  /** Baseline of this group's name row, when this line heads a group. */
  nameY: number;
  group: number;
  /** First line of a group, i.e. the one the name and avatar belong to. */
  head: boolean;
  text: string;
  /** Frame the words land on. The row itself opens at `opens`. */
  at: number;
  opens: number;
}

/**
 * Lay the transcript out once, in transcript space.
 *
 * Positions are absolute and never re-flow: the scroll is a single translate
 * over the top of them. That is what lets every arrival be a number rather than
 * a layout pass, and it is why the stack can be perfectly still between them.
 */
function layout(
  groups: { person: string; time: string; lines: string[] }[],
): Line[] {
  const out: Line[] = [];
  let last = START_Y - NAME_GAP;
  let first = true;
  for (let g = 0; g < groups.length; g++) {
    const group = groups[g];
    if (!group) continue;
    for (let m = 0; m < group.lines.length; m++) {
      const head = m === 0;
      const nameY = head ? (first ? last : last + GROUP_GAP) : 0;
      const y = head ? nameY + NAME_GAP : last + MSG_GAP;
      out.push({
        y,
        nameY,
        group: g,
        head,
        text: group.lines[m] ?? "",
        at: 0,
        opens: 0,
      });
      last = y;
      first = false;
    }
  }
  return out;
}

/**
 * One message. A message with the same author, time and avatar as the one
 * above it joins that group, under one name, the way the channel reads.
 */
export interface ThreadMessage {
  text: string;
  author?: string;
  time?: string;
  avatar?: string;
  /** Frame the words land on. Default: the measured 0, 12, 60, 84, then every 24. */
  at?: number;
  /**
   * Frame the row opens on, before the words land — typing dots, if it starts
   * a group. Default: the measured 0, 12, 37, 72, then every 24.
   */
  opens?: number;
}

/** The recording's four arrivals; after them, a message every 24 frames. */
const BEATS = [0, 12, 60, 84];
const OPENS = [0, 12, 37, 72];

/**
 * The string form of `messages`, for the customizer and for quick edits:
 * messages split by `|`, each `avatar > name time > text`. The name runs to
 * the first space. A message that is only text continues the one above it.
 *
 *   "/avatars/07.jpg > rhea 9:41 AM > Launch video? | Nothing shot."
 */
function toMessages(
  input: readonly ThreadMessage[] | string,
): readonly ThreadMessage[] {
  if (typeof input !== "string") return input;
  let head = { author: "", time: "", avatar: "" };
  return input
    .split("|")
    .filter((m) => m.trim())
    .map((m) => {
      const parts = m.split(">").map((v) => v.trim());
      const text = parts.pop() ?? "";
      const who = parts.pop();
      if (who !== undefined) {
        const cut = who.indexOf(" ");
        head = {
          author: cut < 0 ? who : who.slice(0, cut),
          time: cut < 0 ? "" : who.slice(cut + 1),
          avatar: parts.pop() ?? "",
        };
      }
      return { ...head, text };
    });
}

export interface ChannelThreadProps {
  /** The conversation, in order. Also takes the string form: see `toMessages`. */
  messages?: readonly ThreadMessage[] | string;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  fontFamily?: string;
}

function ChannelThreadScene({
  messages = ChannelThreadDefaults.messages,
  theme,
  mode = "light",
  fontFamily = "Default",
}: ChannelThreadProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily) ?? SANS;

  const u = height / REF_H;
  const ox = (width - REF_W * u) / 2;
  const now = frame / fps;

  const said = toMessages(messages).filter((m) => m.text.trim());
  const groups: {
    person: string;
    time: string;
    avatar: string;
    lines: string[];
  }[] = [];
  for (const m of said) {
    const [person = "", time = "", avatar = ""] = [m.author, m.time, m.avatar];
    const g = groups[groups.length - 1];
    if (g && g.person === person && g.time === time && g.avatar === avatar) {
      g.lines.push(m.text.trim());
    } else {
      groups.push({ person, time, avatar, lines: [m.text.trim()] });
    }
  }

  const lines = layout(groups);
  lines.forEach((l, i) => {
    const m = said[i];
    l.at = m?.at ?? BEATS[i] ?? 84 + 24 * (i - 3);
    l.opens =
      i === 0
        ? Number.NEGATIVE_INFINITY
        : (m?.opens ?? OPENS[i] ?? 72 + 24 * (i - 3));
  });

  // Each opened row moves the target to however far its baseline falls past the
  // anchor. A row that does not reach the anchor moves nothing, which is the
  // stillness in the reference rather than an exception carved out for it.
  let scroll = 0;
  let target = 0;
  for (const l of lines) {
    const want = Math.max(0, l.y - ANCHOR);
    const step = want - target;
    target = want;
    if (step <= 0) continue;
    // A longer move takes *less* time, not more — measured, twice: the two-row
    // scroll runs 1.60× faster in normalised time than the one-row scroll, which
    // is what a browser's native smooth scroll does with distance and what the
    // recording therefore does. One curve, read faster the further it has to go.
    const rate = (step / MSG_GAP) ** 0.68;
    scroll += step * read(SCROLL, (now - l.opens / fps) * rate);
  }

  const ink = t.foreground;
  const dim = t.mutedForeground;

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ backgroundColor: t.background }}
    >
      <div
        style={{
          position: "absolute",
          left: ox,
          top: 0,
          width: REF_W * u,
          height: REF_H * u,
          fontFamily: face,
          // Hinting re-snaps every stem as a line slides past, and the
          // letterforms boil. This renders the outline as it actually is.
          textRendering: "geometricPrecision",
          whiteSpace: "nowrap",
          overflow: "hidden",
        }}
      >
        {lines.map((l, i) => {
          const y = l.y - scroll;
          if (y < -MSG_GAP || y > REF_H + MSG_GAP) return null;
          const shown = frame >= l.at;
          if (frame < l.opens) return null;
          const arrived = frame >= l.opens + LEAD;
          const g = groups[l.group];
          const nameA = read(FADE, y - NAME_GAP);
          const bodyA = read(FADE, y);
          return (
            <div key={`${l.group}-${i}`}>
              {l.head && g && arrived && (
                <>
                  <Avatar
                    src={g.avatar}
                    name={g.person}
                    y={(y - NAME_GAP - AVATAR_RISE) * u}
                    u={u}
                    t={t}
                    alpha={read(FADE, y - NAME_GAP - AVATAR_RISE + AVATAR / 2)}
                  />
                  <div
                    style={{
                      position: "absolute",
                      left: TEXT_X * u,
                      top: (y - NAME_GAP - ASC) * u,
                      fontSize: SIZE * u,
                      lineHeight: 1,
                      fontWeight: 700,
                      color: ink,
                      // Per row, not per group. The name sits 37.59px above its
                      // first message and the gradient moves measurably over
                      // that distance — sharing one opacity between them reads
                      // as a name that refuses to leave.
                      opacity: nameA,
                    }}
                  >
                    {g.person}
                    <span
                      style={{
                        fontSize: TIME_SIZE * u,
                        fontWeight: 500,
                        color: dim,
                        // The timestamp rides the name's baseline, so it is one
                        // inline run and not a second absolutely-placed box to
                        // keep in step when the name's width changes.
                        marginLeft: 13.4 * u,
                      }}
                    >
                      {g.time}
                    </span>
                  </div>
                </>
              )}
              {shown ? (
                // The message is the object Studio selects: its body line, by
                // its index across the whole conversation.
                <Item index={i}>
                  <div
                    style={{
                      position: "absolute",
                      left: TEXT_X * u,
                      top: (y - ASC) * u,
                      fontSize: SIZE * u,
                      lineHeight: 1,
                      color: ink,
                      opacity: bodyA,
                    }}
                  >
                    {l.text}
                  </div>
                </Item>
              ) : (
                l.head &&
                arrived && (
                  <Dots
                    y={(y - DOT_RISE) * u}
                    u={u}
                    colour={mixOklch(dim, ink, 0.3)}
                    since={now - (l.opens + LEAD) / fps}
                    alpha={bodyA}
                  />
                )
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}

/** Three dots that arrive one at a time, then start over. */
function Dots({
  y,
  u,
  colour,
  since,
  alpha,
}: {
  y: number;
  u: number;
  colour: string;
  since: number;
  alpha: number;
}) {
  const step = Math.floor((since % (DOT_BEAT * 4)) / DOT_BEAT);
  return (
    <>
      {[0, 1, 2].map((i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            left: (TEXT_X + 3.3 + i * DOT_GAP) * u,
            top: y - (DOT / 2) * u,
            width: DOT * u,
            height: DOT * u,
            borderRadius: "50%",
            background: colour,
            opacity: i < step ? alpha : 0,
          }}
        />
      ))}
    </>
  );
}

/**
 * A root-relative asset is a `public/` file. Only the site's own Player serves
 * it at that path; Remotion Studio and a render know its URL through
 * `staticFile()` alone — so every environment but the Player rewrites it.
 */
function resolveSrc(src: string): string {
  const isLocal = src.startsWith("/") && !src.startsWith("//");
  if (!isLocal || getRemotionEnvironment().isPlayer) return src;
  // A value that already came out of staticFile() carries the static base
  // (`/static-<hash>/…`); running it through again would prefix it twice.
  const base = staticFile("_").slice(0, -2);
  if (base && src.startsWith(`${base}/`)) return src;
  try {
    return staticFile(src.replace(/^\/+/, ""));
  } catch {
    return src;
  }
}

/**
 * An avatar that holds the render until it has actually loaded.
 *
 * Without this a frame can be captured before the picture arrives and the
 * square comes out empty — invisible in the Player, where an image simply
 * appears, and silent in an mp4 until somebody watches it. Remotion's own `Img`
 * is avoided for the reason `hero-launch` documents: it awaits `decode()`, which
 * the headless compositor rejects for some progressive JPEGs and hangs the
 * export. `onError` releases too, so a bad source degrades to a missing picture
 * rather than a stuck render.
 */
function Face({ src, style }: { src: string; style: CSSProperties }) {
  const [handle] = useState(() => delayRender(`channel avatar: ${src}`));
  const release = useCallback(() => continueRender(handle), [handle]);
  return (
    // biome-ignore lint/performance/noImgElement: Remotion frame, not a Next route.
    <img // eslint-disable-line @remotion/warn-native-media-tag -- onLoad releases the frame; <Img> hangs on some JPEGs
      src={resolveSrc(src)}
      alt=""
      // Tailwind's preflight sets `img { max-width: 100% }`, which collapses an
      // image inside a shrink-to-fit box to zero pixels wide on the site while
      // rendering perfectly in an mp4. Size it here and say so.
      style={{ ...style, maxWidth: "none" }}
      onLoad={release}
      onError={release}
    />
  );
}

/** The person's picture, or their initial on a tinted square when there is none. */
function Avatar({
  src,
  name,
  y,
  u,
  t,
  alpha,
}: {
  src: string;
  name: string;
  y: number;
  u: number;
  t: KitTheme;
  alpha: number;
}) {
  const box = {
    position: "absolute" as const,
    left: AVATAR_X * u,
    top: y,
    width: AVATAR * u,
    height: AVATAR * u,
    borderRadius: 8 * u,
    overflow: "hidden" as const,
    opacity: alpha,
  };
  if (src) return <Face src={src} style={{ ...box, objectFit: "cover" }} />;
  return (
    <div
      style={{
        ...box,
        // A tinted tile with the accent's own letter on it: legible on either
        // theme, and it moves with a user's palette instead of inventing a grey.
        // An alpha tint rather than a mix — the page is a near-neutral, its hue
        // in oklch is undefined, and interpolating toward the accent through it
        // comes out somewhere else entirely. Measured: a blue accent over the
        // warm off-white page mixed to a pale *green*.
        background: withAlpha(t.primary, 0.16),
        color: t.primary,
        fontSize: AVATAR * 0.45 * u,
        fontWeight: 600,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {name.slice(0, 1).toUpperCase()}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio: one message at a time
   ───────────────────────────────────────────────────────────────────────── */

/**
 * Everything `el` paints that can be seen, in page pixels: its text runs, its
 * media, and every box with a fill or a border, each cut to every box that
 * clips it up to and including `root` (the Element's own box). Null when none
 * of it shows — transparent, or clipped out of the Element.
 */
function ChannelThreadPainted(
  el: Element,
  root: Element,
): [number, number, number, number] | null {
  let u: [number, number, number, number] | null = null;
  const add = (r: DOMRect, from: Element) => {
    // Never past the Element's own box, clipped or not: a text run's line box
    // stands above its ink, and no scene's ink leaves its box (measured).
    const c0 = root.getBoundingClientRect();
    let b: [number, number, number, number] = [
      Math.max(r.left, c0.left),
      Math.max(r.top, c0.top),
      Math.min(r.right, c0.right),
      Math.min(r.bottom, c0.bottom),
    ];
    let alpha = 1;
    for (
      let a: Element | null = from;
      a;
      a = a === root ? null : a.parentElement
    ) {
      const cs = getComputedStyle(a);
      if (cs.visibility === "hidden") return;
      alpha *= Number(cs.opacity);
      if (a !== from && a !== root && cs.overflow !== "visible") {
        const c = a.getBoundingClientRect();
        b = [
          Math.max(b[0], c.left),
          Math.max(b[1], c.top),
          Math.min(b[2], c.right),
          Math.min(b[3], c.bottom),
        ];
      }
    }
    if (alpha < 0.02 || b[2] <= b[0] || b[3] <= b[1]) return;
    u = u
      ? [
          Math.min(u[0], b[0]),
          Math.min(u[1], b[1]),
          Math.max(u[2], b[2]),
          Math.max(u[3], b[3]),
        ]
      : b;
  };
  const walk = (e: Element) => {
    const cs = getComputedStyle(e);
    if (cs.display === "none") return;
    const media = /^(img|video|canvas|svg)$/i.test(e.tagName);
    if (
      media ||
      cs.backgroundColor !== "rgba(0, 0, 0, 0)" ||
      cs.backgroundImage !== "none" ||
      parseFloat(cs.borderTopWidth) > 0
    )
      add(e.getBoundingClientRect(), e);
    if (media) return;
    for (const n of Array.from(e.childNodes)) {
      if (n.nodeType === Node.TEXT_NODE && n.textContent?.trim()) {
        const range = document.createRange();
        range.selectNodeContents(n);
        for (const r of Array.from(range.getClientRects())) add(r, e);
      } else if (n.nodeType === Node.ELEMENT_NODE) walk(n as Element);
    }
  };
  walk(el);
  return u;
}
type ChannelThreadMessageValues = {
  readonly text?: string;
  readonly author?: string;
  readonly time?: string;
  readonly avatar?: string;
};

type ChannelThreadMessageProps = InteractiveBaseProps &
  Omit<InteractiveTransformProps, "style"> &
  ChannelThreadMessageValues & {
    readonly style?: CSSProperties | null;
    /** The node the scene draws this message as, while it draws it; set by the stage, never by hand. */
    readonly claim?: { current: Element | null };
    /** The box its outline falls back to when the node is not all there; set by the stage too. */
    readonly slot?: { current: HTMLDivElement | null };
    /** Hands Studio's live props back to the stage, which draws the node; set by the stage too. */
    readonly report?: (state: ChannelThreadMessageState) => void;
  };

/** What Studio is doing to one message right now, which the stage applies to its node. */
type ChannelThreadMessageState = {
  values: ChannelThreadMessageValues;
  style?: CSSProperties;
  hidden?: boolean;
  from?: number;
  durationInFrames?: number;
};

const ChannelThreadMessageSchema = {
  ...Interactive.baseSchema,
  text: { type: "text-content", default: "", description: "Message" },
  author: { type: "text-content", default: "", description: "Author" },
  time: { type: "text-content", default: "", description: "Time" },
  avatar: {
    type: "asset",
    assetType: "image",
    default: undefined,
    description: "Avatar",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

/**
 * One message: its layer in Studio. The scene decides where it is on every
 * frame and draws it; this is the Sequence Studio lists, selects and outlines,
 * mounted for the Element's whole length so the layer never leaves the
 * timeline while the message is off the frame. It draws nothing itself: its
 * values, transform, visibility and timing reach the node through the stage.
 */
const ChannelThreadMessageInner = forwardRef<
  Element,
  ChannelThreadMessageProps & {
    readonly controls: SequenceControls | undefined;
  }
>(
  (
    {
      controls,
      name,
      style,
      from,
      durationInFrames,
      trimBefore,
      playbackRate,
      loop,
      freeze,
      hidden,
      showInTimeline,
      claim,
      slot,
      report,
      text,
      author,
      time,
      avatar,
    },
    ref,
  ) => {
    // What Studio outlines, chosen every frame: the node itself — its exact
    // quad, transforms and all — while all of it shows; a box over the part
    // that does when the Element clips it, or when its parts move separately; nothing while none of it
    // shows, so an object that has left is not still selectable where it was.
    const target = useRef<Element | null>(null);
    // Re-rendered every frame, so the outline is chosen for every frame: the
    // scene moves the node without re-rendering this layer.
    useCurrentFrame();
    // Studio reads the ref every time it measures.
    const outline = useRef({
      get current() {
        return target.current ?? claim?.current ?? null;
      },
    }).current;
    // Studio's live props arrive here — a value being typed, a transform being
    // dragged, the layer hidden or retimed — and the stage draws the node.
    useLayoutEffect(() => {
      report?.({
        values: { text, author, time, avatar },
        style: style ?? undefined,
        hidden,
        from,
        durationInFrames,
      });
    });
    useImperativeHandle(ref, () => claim?.current as Element);
    useLayoutEffect(() => {
      // Outlines are a Studio thing; a render or the Player measures nothing.
      if (!getRemotionEnvironment().isStudio) return;
      const box = slot?.current;
      const root = box?.parentElement;
      if (!box || !root) return;
      const el = claim?.current;
      const b = el ? ChannelThreadPainted(el, root) : null;
      if (!el || !b) {
        box.style.display = "none";
        target.current = box;
        return;
      }
      const r = root.getBoundingClientRect();
      const k = root.offsetWidth / (r.width || 1);
      box.style.display = "block";
      box.style.left = `${(b[0] - r.left) * k}px`;
      box.style.top = `${(b[1] - r.top) * k}px`;
      box.style.width = `${(b[2] - b[0]) * k}px`;
      box.style.height = `${(b[3] - b[1]) * k}px`;
      target.current = box;
    });
    return (
      <Sequence
        layout="none"
        from={from}
        durationInFrames={durationInFrames}
        trimBefore={trimBefore}
        playbackRate={playbackRate}
        loop={loop}
        freeze={freeze}
        hidden={hidden}
        showInTimeline={showInTimeline}
        name={name ?? "Message"}
        controls={controls}
        outlineRef={outline}
      />
    );
  },
);

const ChannelThreadMessage = Interactive.withSchema({
  Component: ChannelThreadMessageInner,
  componentName: "<ChannelThreadMessage>",
  schema: ChannelThreadMessageSchema,
  supportsEffects: false,
});

